// spec: specs/catalog.md §17 · кейсы .qa/tests/catalog/cat-30-import-manual-column-mapping.md, cat-31-import-mapped-barcode-check-digit.md
// seed: tests/seed.admin.spec.ts
// #6ac0be (באג, עבר QA 29.10, commit 8c22452): ручная привязка нераспознанной колонки к полю в импорте из Excel.
//   «מה רצוי»: в «שינוי עמודות» можно выбрать для любого поля колонку файла, в том числе нераспознанную
//   («מחיר לצרכן» ← «מחיר בסיס»); ручная привязка работает и когда модель недоступна / ничего не распознала (#7c5052 AC4).
//   Реализация: нераспознанная колонка — кнопка «שיוך העמודה «X» לנתון» (в пояснении «עמודה נוספת…» и внизу панели
//   «התאמת עמודות»), клик → меню полей; после выбора строка поля «מהעמודה «X»» и переключатель включён. Поле без колонки:
//   «לא זוהתה עמודה · אפשר לשייך עמודה מהרשימה למטה». Опоздавший ответ модели не затирает ручной выбор.
//   Рамки реджекта #7c5052: в строках полей нет Dropdown/select, нет «יחידת מכירה».
// Модель: ответ functions/v1/import-map ВСЕГДА подменён (../_ai-mock.ts) — настоящего (платного) вызова нет.
// Запись: blockWrites (../_ai-mock.ts) блокирует запись в базу; где нужен «ייבוא» — POST products перехвачен (201 [], в базу не уходит).
// Записан вручную (запасной путь): официальный генератор не умеет подменять import-map и перехватывать запись.
import { test, expect, Page } from '@playwright/test';
import * as H from '../inventory/_places';
import { mockAi, blockWrites, VARIANTS, IMPORT_MAP_EMPTY, AiMock } from '../_ai-mock';
import * as I from './_import';

test.use({ storageState: H.ADMIN });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-6ac0be-${TS}`;
const FIELDS = ['שם מוצר', 'מק"ט', 'קטגוריה', 'כמות באריזה', 'מחיר קנייה', 'מחיר בסיס', 'תיאור', 'זמין למכירה'];
const NOTE_BALANCE = /זיהוי עמודות אוטומטי אינו זמין כרגע/;
const NOTE_GENERIC = 'לא הצלחנו לזהות את שאר העמודות אוטומטית. שייכו אותן ידנית.';

async function start(page: Page, status: number, body: unknown) {
  const writes = await blockWrites(page);
  const ai = await mockAi(page, 'import-map', status, body);
  await I.openImport(page);
  return { writes, ai };
}

async function openPanel(page: Page) {
  await page.getByRole('button', { name: 'שינוי עמודות' }).first().click();
  await expect(page.getByRole('heading', { name: 'התאמת עמודות' })).toBeVisible();
}

/** Привязать колонку к полю через кнопку колонки → меню. */
async function mapCol(page: Page, col: string, field: string | RegExp) {
  await I.chip(page, col).last().click();
  await page.getByRole('menuitem', { name: field }).click();
}

test.describe('catalog — ייבוא מאקסל: שיוך ידני של עמודה שלא זוהתה (#6ac0be)', () => {
  test('«מחיר לצרכן» → «מחיר בסיס» דרך כפתור העמודה: ההסבר מוביל לכפתור, תפריט כל השדות, «מהעמודה «מחיר לצרכן»», מחיר בתצוגה ובייבוא; כיבוי מסיר; בלי Dropdown ובלי «יחידת מכירה» (מודל: 200, columns ריק) #6ac0be @desktop @catalog @prod-safe', async ({ page }) => {
    const { writes, ai } = await start(page, 200, IMPORT_MAP_EMPTY);
    await I.upload(page, `שם מוצר,מחיר לצרכן\n${P}-a,12.5\n`);
    const more = page.getByRole('button', { name: 'עמודה נוספת אחת לא תיובא', exact: true });
    await expect(more).toBeVisible({ timeout: 20_000 });
    await expect.poll(() => ai.hits, { message: 'нераспознанная колонка ушла в (подменённую) модель' }).toBe(1);
    await more.click();
    await expect(page.locator('main').getByText(I.HINT).first()).toBeVisible();
    await expect(page.locator('main').getByText(/פתחו «שינוי עמודות» ובחרו לה שדה/)).toHaveCount(0);
    await expect(I.chip(page, 'מחיר לצרכן')).toHaveCount(1);

    await I.chip(page, 'מחיר לצרכן').click();
    const items = page.getByRole('menu').getByRole('menuitem');
    await expect(items).toHaveCount(FIELDS.length);
    for (const f of FIELDS) await expect(items.filter({ hasText: f }).first(), `в меню есть «${f}»`).toBeVisible();
    await expect(page.getByRole('menu')).not.toContainText('יחידת מכירה');
    await page.keyboard.press('Escape');
    await expect(page.getByRole('menu')).toHaveCount(0);

    await openPanel(page);
    for (const f of ['מק"ט', 'קטגוריה', 'כמות באריזה', 'מחיר קנייה', 'מחיר בסיס', 'תיאור', 'זמין למכירה']) {
      await expect(I.fieldRow(page, f), `«${f}» без колонки`).toContainText(I.NO_COL);
    }
    const panel = page.locator('main').getByRole('list').first();
    await expect(panel.locator('select, [role=combobox], [aria-haspopup=listbox]'), 'в строках полей нет Dropdown').toHaveCount(0);
    await expect(page.locator('main')).not.toContainText('יחידת מכירה');
    await expect(I.chip(page, 'מחיר לצרכן'), 'кнопка колонки и внизу панели').toBeVisible();

    await mapCol(page, 'מחיר לצרכן', 'מחיר בסיס');
    await expect(I.fieldRow(page, 'מחיר בסיס')).toContainText(I.fromCol('מחיר לצרכן'));
    await expect(page.getByRole('switch', { name: 'ייבוא מחיר בסיס' })).toHaveAttribute('aria-checked', 'true');
    await expect(I.priceCell(page, 1)).toHaveValue('12.5');
    await expect(I.chip(page, 'מחיר לצרכן'), 'колонка больше не в списке «לא תיובא»').toHaveCount(0);

    // Выключить → цены в предпросмотре нет, колонка снова в списке; включить обратно.
    await page.getByRole('switch', { name: 'ייבוא מחיר בסיס' }).click();
    await expect(I.priceCell(page, 1)).toHaveCount(0);
    await expect(I.chip(page, 'מחיר לצרכן')).toBeVisible();
    await mapCol(page, 'מחיר לצרכן', 'מחיר בסיס');
    await expect(I.priceCell(page, 1)).toHaveValue('12.5');

    expect(writes, 'до «ייבוא» ничего не записано').toEqual([]);
    const posted = await I.fakeProductInsert(page);
    await I.importBtn(page).click();
    await expect.poll(() => posted.length, { message: 'POST products (перехвачен)' }).toBe(1);
    expect(posted[0][0].name).toBe(`${P}-a`);
    expect(Number(posted[0][0].base_price), 'מחיר בסיס из колонки «מחיר לצרכן»').toBe(12.5);
    expect(ai.hits, 'модель вызвана один раз (подмена)').toBe(1);
  });

  for (const [label, status, body, note] of [
    ['יתרה נגמרה (200, error)', VARIANTS['error-200'].status, VARIANTS['error-200'].body, NOTE_BALANCE],
    ['500 timeout', VARIANTS['timeout-500'].status, VARIANTS['timeout-500'].body, NOTE_GENERIC],
  ] as const) {
    test(`מודל לא זמין — ${label}: יש הערה, השיוך הידני עובד («מחיר לצרכן» → «מחיר בסיס») #6ac0be @desktop @catalog @prod-safe`, async ({ page }) => {
      const { writes, ai } = await start(page, status, body);
      await I.upload(page, `שם מוצר,מחיר לצרכן\n${P}-b,12.5\n`);
      await expect.poll(() => ai.hits, { timeout: 20_000 }).toBe(1);
      await openPanel(page);
      await expect(page.locator('main').getByText(note).first()).toBeVisible();
      await mapCol(page, 'מחיר לצרכן', 'מחיר בסיס');
      await expect(I.fieldRow(page, 'מחיר בסיס')).toContainText(I.fromCol('מחיר לצרכן'));
      await expect(I.priceCell(page, 1)).toHaveValue('12.5');
      await expect(I.importBtn(page)).toBeEnabled();
      expect(writes).toEqual([]);
    });
  }

  test('תשובת מודל מאוחרת (5 שניות) לא דורסת שיוך ידני ומתג שכובה בזמן ההמתנה #6ac0be @desktop @catalog @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    const writes = await blockWrites(page);
    const ai: AiMock = await mockAi(page, 'import-map', 200,
      { ok: true, columns: [{ column: 2, field: 'cost_price' }, { column: 3, field: 'description' }], units: [], categories: [], dropped: 0, model: 'mock' });
    ai.delay = 5_000;
    await I.openImport(page);
    await I.upload(page, `שם מוצר,קוד מוצר,מחיר לצרכן,זרזיף קרפלוני\n${P}-c,QA-${TS}-SKU1,12.5,טקסט\n`);
    await openPanel(page);
    await expect(I.fieldRow(page, 'מק"ט')).toContainText(I.fromCol('קוד מוצר'));
    await mapCol(page, 'מחיר לצרכן', 'מחיר בסיס');
    await page.getByRole('switch', { name: 'ייבוא מק"ט' }).click();
    await expect(page.getByRole('switch', { name: 'ייבוא מק"ט' })).toHaveAttribute('aria-checked', 'false');
    expect(ai.hits, 'ответ модели ещё не пришёл').toBe(1);

    // Ответ модели (через 5 с) предлагает «מחיר לצרכן» → מחיר קנייה и «זרזיף קרפלוני» → תיאור.
    await expect(page.getByText('עמודה אחת זוהתה אוטומטית ומסומנת למטה — בדקו אותה לפני הייבוא.')).toBeVisible({ timeout: 15_000 });
    await expect(I.fieldRow(page, 'תיאור')).toContainText(I.fromCol('זרזיף קרפלוני'));
    await expect(I.fieldRow(page, 'מחיר בסיס'), 'ручная привязка сохранилась').toContainText(I.fromCol('מחיר לצרכן'));
    await expect(page.getByRole('switch', { name: 'ייבוא מחיר בסיס' })).toHaveAttribute('aria-checked', 'true');
    await expect(I.fieldRow(page, 'מחיר קנייה'), 'подсказка модели не забрала колонку').not.toContainText(I.fromCol('מחיר לצרכן'));
    await expect(page.getByRole('switch', { name: 'ייבוא מק"ט' }), 'выключенный переключатель остался выключен').toHaveAttribute('aria-checked', 'false');
    await expect(I.priceCell(page, 1)).toHaveValue('12.5');
    await expect(I.skuCell(page, 1)).toHaveValue('');
    expect(writes).toEqual([]);
  });

  test('עמודה לשדה תפוס מחליפה את הקודמת: «זרזיף קרפלוני» → «מחיר בסיס במקום העמודה «מחיר לצרכן»»; הקודמת חוזרת לרשימה #6ac0be @desktop @catalog @prod-safe', async ({ page }) => {
    const { writes } = await start(page, 200, IMPORT_MAP_EMPTY);
    await I.upload(page, `שם מוצר,מחיר לצרכן,זרזיף קרפלוני\n${P}-d,12.5,7\n`);
    await openPanel(page);
    await mapCol(page, 'מחיר לצרכן', 'מחיר בסיס');
    await expect(I.priceCell(page, 1)).toHaveValue('12.5');
    await I.chip(page, 'זרזיף קרפלוני').click();
    const replace = page.getByRole('menuitem', { name: /^מחיר בסיס במקום העמודה «⁨?מחיר לצרכן⁩?»$/ });
    await expect(replace).toBeVisible();
    await replace.click();
    await expect(I.fieldRow(page, 'מחיר בסיס')).toContainText(I.fromCol('זרזיף קרפלוני'));
    await expect(I.priceCell(page, 1)).toHaveValue('7');
    await expect(page.getByRole('textbox', { name: /^מחיר, שורה 1$/ }), 'одна колонка цены, без двойного маппинга').toHaveCount(1);
    await expect(I.chip(page, 'מחיר לצרכן'), 'прежняя колонка снова «לא תיובא»').toBeVisible();
    await expect(I.chip(page, 'זרזיף קרפלוני')).toHaveCount(0);
    expect(writes).toEqual([]);
  });

  test('קובץ בלי עמודת שם: «לא זוהתה עמודת "שם מוצר"», ייבוא חסום → «תווית» → «שם מוצר» → השמות בתצוגה, ייבוא פעיל #6ac0be @desktop @catalog @prod-safe', async ({ page }) => {
    const { writes } = await start(page, 200, IMPORT_MAP_EMPTY);
    await I.upload(page, `תווית,קוד מוצר\n${P}-e,QA-${TS}-SKU2\n`);
    const alert = page.getByRole('alert').filter({ hasText: 'לא זוהתה עמודת "שם מוצר" בקובץ' });
    await expect(alert).toBeVisible({ timeout: 20_000 });
    await expect(alert).toContainText('לחצו על העמודה הנכונה ברשימה למעלה ובחרו «שם מוצר»');
    await expect(page.getByRole('button', { name: 'ייבוא 0 מוצרים' }).first()).toBeDisabled();
    await expect(I.fieldRow(page, 'שם מוצר')).toContainText(I.NO_COL);
    await mapCol(page, 'תווית', /^שם מוצר/);
    await expect(I.nameCell(page, 1)).toHaveValue(`${P}-e`);
    await expect(I.fieldRow(page, 'שם מוצר')).toContainText(I.fromCol('תווית'));
    await expect(alert).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'ייבוא מוצר אחד' }).first()).toBeEnabled();
    expect(writes).toEqual([]);
  });

  test('«ברקוד ספק» עם EAN שגוי, משויך ידנית ל«מק"ט» — מקבל סימון ספרת ביקורת (#dc1afa) #6ac0be #dc1afa @desktop @catalog @prod-safe', async ({ page }) => {
    const C = I.codes();
    const { writes } = await start(page, 200, IMPORT_MAP_EMPTY);
    await I.upload(page, `שם מוצר,מחיר,ברקוד ספק\n${P}-ean,9.9,${C.E13bad}\n`);
    const more = page.getByRole('button', { name: 'עמודה נוספת אחת לא תיובא', exact: true });
    await expect(more).toBeVisible({ timeout: 20_000 });
    await expect(I.anyCounter(page), 'до привязки отметки нет').toHaveCount(0);
    await more.click();
    await mapCol(page, 'ברקוד ספק', /^מק"ט$/);
    const cell = I.skuCell(page, 1);
    await expect(cell).toHaveValue(C.E13bad);
    await expect(cell).toHaveAttribute('aria-invalid', 'true');
    await expect(I.warnings(page)).toHaveCount(1);
    await expect(I.counter(page, 1)).toBeVisible();
    await I.importBtn(page).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'לייבא מק"ט עם ספרת ביקורת שגויה?' })).toBeVisible();
    await dlg.getByRole('button', { name: 'תיקון המק"ט', exact: true }).click();
    await expect(dlg).toHaveCount(0);
    expect(writes).toEqual([]);
  });
});
